def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 20.0))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
            urgent_opp += 1
        if opp.get('budget', 0) >= 300:
            rich_opp += 1

    prev_bids.sort()
    max_prev = prev_bids[-1] if prev_bids else 0.0
    med_prev = prev_bids[int(len(prev_bids) // 2)] if prev_bids else 0.0

    scarcity = 1.0
    if supply <= 16:
        scarcity = 1.25
    elif supply >= 23:
        scarcity = 0.8

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water >= 2:
        danger += 2
    elif no_water >= 1:
        danger += 1

    if danger >= 3:
        target = max(95.0, med_prev * 0.92, max_prev * 0.82)
        target *= scarcity
    elif danger >= 2:
        target = max(62.0, med_prev * 0.62)
        target *= scarcity
    else:
        target = 22.0 + 4.0 * no_water
        if max_prev > 120:
            target = min(target, 32.0)
        elif max_prev < 80:
            target = max(target, max_prev + 2.0)
        target *= scarcity

    if urgent_opp >= 2 and danger <= 1:
        target *= 0.85
    if rich_opp >= 2 and danger >= 2:
        target *= 1.08

    if day >= 8:
        target *= 1.08
    if hp >= 8 and no_water == 0 and supply >= 22:
        target *= 0.85

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 35.0
    max_affordable = max(0.0, budget - reserve_floor)
    if danger >= 3:
        max_affordable = budget

    bid = min(target, max_affordable if max_affordable > 0 else budget)
    bid = max(0.0, min(bid, budget))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 40)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        target_bid = min(my_status['budget'], max(85, avg_prev * 0.95))
    else:
        target_bid = 85

    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 1.5)

    return int(target_bid)
